-- Generated by tools/build_action_data.py; do not edit.
return {["scripts/actions/weaponskills/blade_retsu.lua"]={["Path"]="scripts/actions/weaponskills/blade_retsu.lua",["SHA256"]="24519a21ba0e9098732f9c3ad4f5b2e32d8ed0ee3eae3ebd1cdf22c895a03a37",["Text"]="-----------------------------------\n-- Blade Retsu\n-- Katana weapon skill\n-- Skill Level: 30\n-- Delivers a two-hit attack. Paralyzes enemy. Duration of paralysis varies with TP.\n-- Proc rate of Paralyze seems to be based on your level in comparison to the targets level. The higher level you are compared to your target, it will be Paralyzed more often.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: None\n-- Modifiers: STR:20%  DEX:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 2\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.PARALYSIS\n    local actionElement = xi.element.ICE\n    local power         = utils.clamp(30 + 3 * (player:getMainLvl() - target:getMainLvl()), 5, 35)\n    local duration      = math.floor(xi.weaponskills.fTP(tp, { 30, 60, 120 }) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_rin.lua"]={["Path"]="scripts/actions/weaponskills/blade_rin.lua",["SHA256"]="921e60e505f7e61989a26e7be3e9d59d38fe14dd406bdeee640ef3082e2dc020",["Text"]="-----------------------------------\n-- Blade Rin\n-- Katana weapon skill\n-- Skill Level: 5\n-- Delivers a single-hit attack. Chance of params.critical varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Light Gorget.\n-- Aligned with the Light Belt.\n-- Element: None\n-- Modifiers: STR:20%  DEX:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.2 params.dex_wsc = 0.2\n    -- TODO: critical hit rate of this ws is base on amount of tp alone, does not consider Critical Hit Rate from dDEX, equipment, or likely merits/base\n    -- https://www.bg-wiki.com/ffxi/Blade:_Rin\n    params.critVaries = { 0.3, 0.6, 0.9 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6 params.dex_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_shun.lua"]={["Path"]="scripts/actions/weaponskills/blade_shun.lua",["SHA256"]="e55117ff45a6edd18be6964bf1d9ddc06df21d9b1477cf5a0339af537eff4663",["Text"]="-----------------------------------\n-- Blade Shun\n-- Katana weapon skill\n-- Skill level: N/A\n-- Description: Delivers a fivefold attack. Attack power varies with TP.\n-- In order to obtain Blade: Shun the quest Martial Mastery must be completed.\n-- This Weapon Skill's first hit params.ftp is duplicated for all additional hits.\n-- Alignet with the Flame Gorget, Light Gorget & Thunder Gorget.\n-- Alignet with the Flame Belt, Light Belt & Thunder Belt.\n-- Element: None\n-- Skillchain Properties: Fusion/Impaction\n-- Modifiers: DEX:73~85%, depending on merit points upgrades.\n-- Damage Multipliers by TP:\n-- 100%        200%      300%\n-- 0.6875    0.6875      0.6875\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 0.6875, 0.6875, 0.6875 }\n    params.dex_wsc = player:getMerit(xi.merit.BLADE_SHUN) * 0.17\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.0, 1.0, 1.0 }\n        params.dex_wsc = 0.7 + (player:getMerit(xi.merit.BLADE_SHUN) * 0.03)\n        params.atkVaries = { 1.0, 2.0, 3.0 } -- http://wiki.ffo.jp/html/25610.html\n        params.multiHitfTP = true -- https://www.bg-wiki.com/ffxi/Blade:_Shun\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_teki.lua"]={["Path"]="scripts/actions/weaponskills/blade_teki.lua",["SHA256"]="f7168c764bb377b57213dd2bb1c1eb292dabd4b5ac675310b8004a545c67bc96",["Text"]="-----------------------------------\n-- Blade Teki\n-- Katana weapon skill\n-- Skill Level: 70\n-- Decription: Deals water elemental damage. Damage varies with TP.\n-- Aligned with the Aqua Gorget.\n-- Aligned with the Aqua Belt.\n-- Element: Water\n-- Modifiers: STR:20%  INT:20%\n-- 100%TP    200%TP    300%TP\n-- 0.50      0.75      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 0.5, 0.75, 1.0 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n    params.hybridWS = true\n    params.ele = xi.element.WATER\n    params.skill = xi.skill.KATANA\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        -- http://wiki.ffo.jp/html/718.html\n        params.str_wsc = 0.3 params.int_wsc = 0.3\n        params.ftpMod = { 0.5, 1.375, 2.25 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_ten.lua"]={["Path"]="scripts/actions/weaponskills/blade_ten.lua",["SHA256"]="f8db2822d61041a07d4c2bb9e0e79d7d56bcbdf6c49f1b2763bbc3d94ff5cca9",["Text"]="-----------------------------------\n-- Blade Ten\n-- Katana weapon skill\n-- Skill Level: 225\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:30%  DEX:30%\n-- 100%TP    200%TP    300%TP\n-- 2.50      2.75      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.5, 2.75, 3.0 }\n    params.str_wsc = 0.3 params.dex_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4.5, 11.5, 15.5 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_to.lua"]={["Path"]="scripts/actions/weaponskills/blade_to.lua",["SHA256"]="f40b4055d0bc98cac1a6db3bb84e0952bce8f6d9d4a649e550299f3dfd97b3a6",["Text"]="-----------------------------------\n-- Blade To\n-- Katana weapon skill\n-- Skill Level: 100\n-- Deals ice elemental damage. Damage varies with TP.\n-- Aligned with the Snow Gorget & Breeze Gorget.\n-- Aligned with the Snow Belt & Breeze Belt.\n-- Element: Ice\n-- Modifiers: STR:30%  INT:30%\n-- 100%TP    200%TP    300%TP\n-- 0.50      0.75      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 0.5, 0.75, 1.0 }\n    params.str_wsc = 0.3 params.int_wsc = 0.3\n    params.hybridWS = true\n    params.ele = xi.element.ICE\n    params.skill = xi.skill.KATANA\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        -- http://wiki.ffo.jp/html/719.html\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n        params.ftpMod = { 0.5, 1.5, 2.5 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blade_yu.lua"]={["Path"]="scripts/actions/weaponskills/blade_yu.lua",["SHA256"]="7b95dd234fb960b90c0ebceb0638e567cdad52a17a2de4b0ff9f83f6329b7272",["Text"]="-----------------------------------\n-- Blade Yu\n-- Katana weapon skill\n-- Skill Level: 290\n-- Delivers a water elemental attack. Additional effect Poison. Durration varies with TP.\n-- Aligned with the Aqua Gorget & Soil Gorget.\n-- Aligned with the Aqua Belt & Soil Belt.\n-- Element: Water\n-- Modifiers: DEX:50%  INT:50%\n-- 100%TP    200%TP    300%TP\n-- 2.25      2.25      2.25\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params      = {}\n    params.ftpMod     = { 2.25, 2.25, 2.25 }\n    params.dex_wsc    = 0.28\n    params.int_wsc    = 0.28\n    params.ele        = xi.element.WATER\n    params.skill      = xi.skill.KATANA\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 3, 3, 3 }\n        params.dex_wsc = 0.4\n        params.int_wsc = 0.4\n    end\n\n    local damage, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Handle status effect\n    local effectId      = xi.effect.POISON\n    local actionElement = xi.element.WATER\n    local power         = 10\n    local duration      = math.floor((75 + 15 * tp / 1000) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, false, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blast_arrow.lua"]={["Path"]="scripts/actions/weaponskills/blast_arrow.lua",["SHA256"]="61527c584bda7c50e6bc8b58d795033dd5ff958785a116ab4e5bc8bde0d0223f",["Text"]="-----------------------------------\n-- Blast Arrow\n-- Archery weapon skill\n-- Skill level: 200\n-- Delivers a melee-distance ranged attack. params.accuracy varies with TP.\n-- Aligned with the Snow Gorget & Light Gorget.\n-- Aligned with the Snow Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:16%  AGI:25%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.00      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.0, 2.0, 2.0 }\n    params.str_wsc = 0.16 params.agi_wsc = 0.25\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.2 params.agi_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/blast_shot.lua"]={["Path"]="scripts/actions/weaponskills/blast_shot.lua",["SHA256"]="e271356555e4697e2365db2fdbe2acb7b60404c20f4a9e70a607cf82ab26cb7b",["Text"]="-----------------------------------\n-- Blast Shot\n-- Marksmanship weapon skill\n-- Skill Level: 200\n-- Delivers a melee-distance ranged attack. params.accuracy varies with TP.\n-- Aligned with the Snow Gorget & Light Gorget.\n-- Aligned with the Snow Belt & Light Belt.\n-- Element: None\n-- Modifiers: AGI:30%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.00      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 2.0, 2.0, 2.0 }\n    params.agi_wsc = 0.3\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.agi_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/bora_axe.lua"]={["Path"]="scripts/actions/weaponskills/bora_axe.lua",["SHA256"]="e3276450901cbb50895cae11e903d99135d02c0f6a2618dd0f97d4b34b24b090",["Text"]="-----------------------------------\n-- Bora Axe\n-- Axe weapon skill\n-- Skill level: 290\n-- Delivers a single-hit ranged attack at a maximum distance of 15.7'. Chance of binding varies with TP\n-- Bind doesn't always break from hitting mob.\n-- This Weapon Skill's first hit params.ftp is duplicated for all additional hits\n-- Not natively available to RNG\n-- Aligned with the ?? Gorget.\n-- Element: Ice\n-- Modifiers: DEX 60%  -- http://wiki.bluegartr.com/bg/Bora_Axe\n-- 100%TP    200%TP    300%TP\n-- 1.0        1.0      1.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 1, 1, 1 }\n    params.dex_wsc   = 0.6\n    params.atkVaries = { 3.5, 3.5, 3.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod    = { 4.5, 4.5, 4.5 }\n        params.dex_wsc   = 1\n        params.atkVaries = { 1, 1, 1 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    if math.randomInt(1, 100) <= tp / 30 * applyResistanceAddEffect(player, target, xi.element.ICE, 0) then\n        local effectId      = xi.effect.BIND\n        local actionElement = xi.element.ICE\n        local power         = 1\n        local duration      = math.floor(20 * applyResistanceAddEffect(player, target, actionElement, 0))\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/brainshaker.lua"]={["Path"]="scripts/actions/weaponskills/brainshaker.lua",["SHA256"]="8472977cc2e7adebf4a54e2310118185a719c9cf890a0803acbd9860f26e15a6",["Text"]="-----------------------------------\n-- Brainshaker\n-- Club weapon skill\n-- Skill level: 70\n-- Stuns enemy. Duration of stun varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Aqua Gorget.\n-- Aligned with the Aqua Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.STUN\n    local actionElement = xi.element.THUNDER\n    local power         = 1\n    local duration      = math.floor(tp / 500 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/burning_blade.lua"]={["Path"]="scripts/actions/weaponskills/burning_blade.lua",["SHA256"]="b9c59859a53ad16d6818986208a292d983500ba946cfa260b1f416cd3ce760f5",["Text"]="-----------------------------------\n-- Burning Blade\n-- Sword weapon skill\n-- Skill Level: 30\n-- Desription: Deals Fire elemental damage to enemy. Damage varies with TP.\n-- Aligned with the Flame Gorget.\n-- Aligned with the Flame Belt.\n-- Element: Fire\n-- Modifiers: STR:20%  INT:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 2.5 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n    params.ele = xi.element.FIRE\n    params.skill = xi.skill.SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.0, 2.1, 3.4 }\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/calamity.lua"]={["Path"]="scripts/actions/weaponskills/calamity.lua",["SHA256"]="d434da6a84af005b929460c201d2c99a1099ca4ba5e318bd0103b257841b4576",["Text"]="-----------------------------------\n-- Calamity\n-- Axe weapon skill\n-- Skill level: 200 (Beastmasters and Warriors only.)\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget & Thunder Gorget.\n-- Aligned with the Soil Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:32%  VIT:32%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      4.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.5, 4.0 }\n    params.str_wsc = 0.32 params.vit_wsc = 0.32\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 2.5, 6.5, 10.375 }\n        params.str_wsc = 0.5 params.vit_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/camlanns_torment.lua"]={["Path"]="scripts/actions/weaponskills/camlanns_torment.lua",["SHA256"]="46ffd2e1b4d96a478a287543884ab33e0c13cf9c63b9e5a9427719b17e412223",["Text"]="-----------------------------------\n-- Camlann's Torment\n-- Polearm weapon skill\n-- Skill Level: EMPYREAN\n-- Delivers a triple damage attack. DEF ignored varies with TP.\n-- Will stack with Sneak Attack.\n-- Element: None\n-- Modifiers: VIT:60%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3           3\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.vit_wsc = 0.6\n    params.ignoredDefense = { 0.15, 0.35, 0.50 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/cataclysm.lua"]={["Path"]="scripts/actions/weaponskills/cataclysm.lua",["SHA256"]="2a9aed782b6f9c38e7ebd4f3d7dc2a37585871d244aa239f0605f9c2ed23b03d",["Text"]="-----------------------------------\n-- Cataclysm\n-- Skill level: 290\n-- Delivers light elemental damage. Additional effect: Flash. Chance of effect varies with TP.\n-- Generates a significant amount of Enmity.\n-- Does not stack with Sneak Attack\n-- Aligned with Aqua Gorget.\n-- Aligned with Aqua Belt.\n-- Properties:\n-- Element: Light\n-- Skillchain Properties:Induration Reverberation\n-- Modifiers: STR:30% MND:30%\n-- Damage Multipliers by TP:\n--     100%TP    200%TP     300%TP\n--      3.00     3.00     3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.str_wsc = 0.3 params.mnd_wsc = 0.3\n    params.ele = xi.element.DARK\n    params.skill = xi.skill.STAFF\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 2.75, 4.0, 5.0 }\n        params.str_wsc = 0.3 params.int_wsc = 0.3 params.mnd_wsc = 0.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/catastrophe.lua"]={["Path"]="scripts/actions/weaponskills/catastrophe.lua",["SHA256"]="a3f6f40884807bfd15069bda50e11eadf4e6daf9b92e69771cfd5eb8a8beef0d",["Text"]="-----------------------------------\n-- Catastrophe\n-- Scythe weapon skill\n-- Skill Level: N/A\n-- Drain target's HP. Bec de Faucon/Apocalypse: Additional effect: Haste\n-- This weapon skill is available with the stage 5 relic Scythe Apocalypse or within Dynamis with the stage 4 Bec de Faucon.\n-- Also available without Aftermath effects with the Crisis Scythe. After 13 weapon skills have been used successfully, gives one \"charge\" of Catastrophe.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: INT:40%  AGI:40%\n-- 100%TP    200%TP    300%TP\n-- 2.75      2.75      2.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    local targetHP = target:getHP()\n    params.numHits = 1\n    params.ftpMod = { 2.75, 2.75, 2.75 }\n    params.agi_wsc = 0.4 params.int_wsc = 0.4\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.agi_wsc = 0.0 params.int_wsc = 0.4\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle HP Drain\n    if not target:isUndead() then\n        local drain = math.floor(damage * math.randomInt(30, 70) / 100) -- TODO: JP Wiki States 50% Heal but all current proof i have shows 30-70%\n\n        drain = utils.clamp(drain, 0, targetHP)\n\n        player:addHP(drain)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/chant_du_cygne.lua"]={["Path"]="scripts/actions/weaponskills/chant_du_cygne.lua",["SHA256"]="2d0a10fe3fd1e5b3ddc7502d5ca034568aa5bc9a89660b234b8038f0790b2b9d",["Text"]="-----------------------------------\n-- Chant du Cygne\n-- Sword weapon skill\n-- Skill level: EMPYREAN\n-- Delivers a three-hit attack. Chance of params.critical varies with TP.\n-- Will stack with Sneak Attack.\n-- Element: None\n-- Modifiers: DEX:60%\n-- 100%TP    200%TP    300%TP\n--         ALL 2.25\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 2.25, 2.25, 2.25 }\n    params.dex_wsc = 0.6\n    params.critVaries = { 0.15, 0.25, 0.4 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.6328125, 1.6328125, 1.6328125 }\n        params.dex_wsc = 0.8\n        params.multiHitfTP = true -- https://www.bg-wiki.com/ffxi/Chant_du_Cygne\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/circle_blade.lua"]={["Path"]="scripts/actions/weaponskills/circle_blade.lua",["SHA256"]="5216455699dd84aefc621418b05bb4bd041fb78f5a4d0a64fd382cb9527a7cc6",["Text"]="-----------------------------------\n-- Circle Blade\n-- Sword weapon skill\n-- Skill Level: 150\n-- Delivers an area of effect attack. Attack radius varies with TP.\n-- Aligned with the Aqua Gorget & Thunder Gorget.\n-- Aligned with the Aqua Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:35%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\n-- TODO: Radius 5y at 2334 TP\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.35\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1.0\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/cloudsplitter.lua"]={["Path"]="scripts/actions/weaponskills/cloudsplitter.lua",["SHA256"]="6571b579a5a67f201b1fcb2182511208411d8781e8f0610110e513b39704db8f",["Text"]="-----------------------------------\n-- Cloudsplitter\n-- Axe weapon skill\n-- Skill level: NA\n-- Description: Deals lightning elemental damage. Damage varies with TP. Farsha: Aftermath.\n-- Available only when equipped with Farsha (85), Farsha (90) or Alard's Axe +1.\n-- Elemental gorgets do not affect damage. Rairin Obi increases damage on Lightning day and/or weather.\n-- Element: Lightning\n-- Modifiers: STR:40% MND:40%\n-- 100%TP    200%TP    300%TP\n-- 3.75        5.0      6.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 3.75, 5.0, 6.0 }\n    params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    params.ele = xi.element.THUNDER\n    params.skill = xi.skill.AXE\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.75, 6.7, 8.5 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/combo.lua"]={["Path"]="scripts/actions/weaponskills/combo.lua",["SHA256"]="fd191295cb1959d060fffecbdb28f1fe4aa0d3b4c64afe9bef4eb60d2ab7bda0",["Text"]="-----------------------------------\n-- Combo\n-- Hand-to-Hand weapon skill\n-- Skill level: 5\n-- Delivers a threefold attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:20%  DEX:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.2 params.dex_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/2416.html\n        params.ftpMod = { 1.0, 2.4, 3.4 }\n        params.str_wsc = 0.3 params.dex_wsc = 0.3\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/coronach.lua"]={["Path"]="scripts/actions/weaponskills/coronach.lua",["SHA256"]="eb208d0e6e631649ea1088a8333780e75162a796b61ba379cdcc46891b2780c8",["Text"]="-----------------------------------\n-- Coronach\n-- Skill Level: N/A\n-- Description: Additional effect: temporarily lowers enmity.\n-- Lowers Enmity for a certain amount of time. (Enmity -20)\n-- Regardless of the damage, Coronach hate is only 80CE / 240 VE (Enmity- effect included).\n-- This weapon skill is only available with the stage 5 relic Gun Annihilator, within Dynamis with the stage 4 Ferdinand or under the latent effect of Exequy Gun.\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Properties\n-- Element: None\n-- Skillchain Properties: Darkness/Fragmentation\n-- Modifiers: DEX:40%  AGI:40%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n--  3.00    3.00    3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.dex_wsc = 0.4\n    params.agi_wsc = 0.4\n    params.overrideCE = 80\n    params.overrideVE = 240\n    params.rangedAccuracyBonus = 100\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.RANGED, xi.aftermath.type.RELIC)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/crescent_moon.lua"]={["Path"]="scripts/actions/weaponskills/crescent_moon.lua",["SHA256"]="8cf655d512c09abbbe9ce55daa467a6152488ac77ea02790383833916b99e163",["Text"]="-----------------------------------\n-- Crescent Moon\n-- Great Sword weapon skill\n-- Skill level: 175\n-- Delivers a single-hit attack. Damage varies with TP.\n-- Modifiers: STR:35%\n-- 100%TP     200%TP     300%TP\n-- 1.0         1.75    2.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 1.0, 1.75, 2.5 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.35\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.5, 1.75, 2.75 }\n        params.str_wsc = 0.8\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/cross_reaper.lua"]={["Path"]="scripts/actions/weaponskills/cross_reaper.lua",["SHA256"]="c270e855dc9df02df3c7f2eb2ff9369031a7f219e9a3b9362bf65dff8c0b08c3",["Text"]="-----------------------------------\n-- Cross Reaper\n-- Scythe weapon skill\n-- Skill level: 225\n-- Delivers a two-hit attack. Damage varies with TP.\n-- Modifiers: STR:30%  MND:30%\n-- 100%TP     200%TP     300%TP\n-- 2.0         2.25    2.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 2.0, 2.25, 2.5 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.3 params.mnd_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 2.0, 4.0, 7.0 }\n        params.str_wsc = 0.6 params.mnd_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/cyclone.lua"]={["Path"]="scripts/actions/weaponskills/cyclone.lua",["SHA256"]="90884fb758454267ffd479fbf3e4f6a539b7a5b48bd3b824d77d950e844ac62f",["Text"]="-----------------------------------\n-- Cyclone\n-- Dagger weapon skill\n-- Skill level: 125\n-- Delivers an area attack that deals wind elemental damage. Damage varies with TP.\n-- This weapon skill is ranged and can be used from a distance (Up to 15').\n-- Directly affected by Magic Attack Bonus.\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Element: Wind\n-- Modifiers: DEX:30%  INT:25%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.38      2.88\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.375, 2.875 }\n    params.dex_wsc = 0.3 params.int_wsc = 0.25\n    params.ele = xi.element.WIND\n    params.skill = xi.skill.DAGGER\n    params.includemab = true\n    params.dStat = xi.mod.INT\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        -- http://wiki.ffo.jp/html/685.html\n        params.dex_wsc = 0.4 params.int_wsc = 0.4\n        params.ftpMod = { 1.0, 2.375, 3.75 }\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/dagan.lua"]={["Path"]="scripts/actions/weaponskills/dagan.lua",["SHA256"]="63166472a37ce1db5c6c8f9caabb3df67bff63b2e4b1b35d93d2ee09064f184d",["Text"]="-----------------------------------\n-- Dagan\n-- Description: Restores HP and MP. Amount restored varies with TP. Gambanteinn: Aftermath.\n-- Acquired permanently by completing the appropriate Walk of Echoes Weapon Skill Trials.\n-- Can also be used by equipping Gambanteinn (85), Gambanteinn (90), Canne de Combat +1 or Canne de Combat +2.\n-- Skillchain Properties: N/A\n-- Modifiers: Max HP / Max MP\n-- Amount restored in HP/MP by TP\n-- Does not deal damage.\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local ftphp = xi.weaponskills.fTP(tp, { 0.22, 0.33, 0.52 })\n    local ftpmp = xi.weaponskills.fTP(tp, { 0.15, 0.22, 0.35 })\n    player:addHP(ftphp * player:getMaxHP())\n    return 0, 0, false, ftpmp * player:getMaxMP()\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/dancing_edge.lua"]={["Path"]="scripts/actions/weaponskills/dancing_edge.lua",["SHA256"]="9f94da32350cd9d6ae48b5901687746580a32fc4f661af043b904bfaff1ec2d4",["Text"]="-----------------------------------\n-- Dancing Edge\n-- Dagger weapon skill\n-- Skill level: 200\n-- Delivers a fivefold attack. params.accuracy varies with TP.\n-- Will stack with Sneak Attack.\n-- Will stack with Trick Attack.\n-- Aligned with the Breeze Gorget & Soil Gorget.\n-- Aligned with the Breeze Belt & Soil Belt.\n-- Element: None\n-- Modifiers: DEX:30%  CHR:40%\n-- 100%TP    200%TP    300%TP\n-- 1.19      1.19      1.19\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 1.1875, 1.1875, 1.1875 }\n    params.dex_wsc = 0.3 params.chr_wsc = 0.4\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 0.4\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/688.html\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/dark_harvest.lua"]={["Path"]="scripts/actions/weaponskills/dark_harvest.lua",["SHA256"]="88007584f837636bc973882eb326a2c462d3c3dd2bb094051684a6acd25d51c2",["Text"]="-----------------------------------\n-- Dark Harvest\n-- Scythe weapon skill\n-- Skill Level: 30\n-- Delivers a dark elemental attack. Damage varies with TP.\n-- Aligned with the Aqua Gorget.\n-- Aligned with the Aqua Belt.\n-- Element: Dark\n-- Modifiers: STR:20%  INT:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 2.5 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n    params.ele = xi.element.DARK\n    params.skill = xi.skill.SCYTHE\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/death_blossom.lua"]={["Path"]="scripts/actions/weaponskills/death_blossom.lua",["SHA256"]="ebe25b3ea277e4eaaff33d47a0b1c7677b17ed5bdfa6891aff6465546aef55c0",["Text"]="-----------------------------------\n-- Death Blossom\n-- Sword weapon skill (RDM main only)\n-- Description: Delivers a threefold attack that lowers target's magic evasion. Chance of lowering target's magic evasion varies with TP. Murgleis: Aftermath effect varies with TP.\n-- Lowers magic evasion by up to 10.\n-- Effect lasts up to 55 seconds.\n-- Available only after completing the Unlocking a Myth (Red Mage) quest.\n-- Aligned with the Breeze Gorget, Thunder Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt, Aqua Belt & Snow Belt.\n-- Modifiers: STR:30%  MND:50%\n-- 100%TP     200%TP      300%TP\n--  4              4           4        new\n-- 1.125      1.125      1.125        old\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 3\n    params.ftpMod  = { 1.125, 1.125, 1.125 }\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4, 4, 4 }\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.MAGIC_EVASION_DOWN\n    local actionElement = xi.element.THUNDER\n    local power         = 10\n    local maccParams =\n    {\n        effectId       = xi.effect.MAGIC_EVASION_DOWN,\n        magicalElement = xi.element.THUNDER,\n        skillType      = xi.skill.SWORD,\n    }\n\n    local resist   = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n    local duration = math.floor(60 * resist) -- TODO: Chance of lowering magic evasion varies with TP.\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/decimation.lua"]={["Path"]="scripts/actions/weaponskills/decimation.lua",["SHA256"]="64c1cbd45b3558a0c2bcbb3189cb58e4ced8449b2ceb8fb50453268768ef0dad",["Text"]="-----------------------------------\n-- Decimation\n-- Axe weapon skill\n-- Skill level: 240\n-- In order to obtain Decimation, the quest Axe the Competition must be completed.\n-- Delivers a three-hit attack. params.accuracy varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Flame Gorget, Light Gorget & Aqua Gorget.\n-- Aligned with the Flame Belt, Light Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 1.25      1.25      1.25\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.25, 1.25, 1.25 }\n    params.str_wsc = 0.5\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.75, 1.75, 1.75 }\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/detonator.lua"]={["Path"]="scripts/actions/weaponskills/detonator.lua",["SHA256"]="8a26a48276a8f8b0474ec52c238359a22ec22912c05d0471d2225ac6b79a578c",["Text"]="-----------------------------------\n-- Detonator\n-- Marksmanship weapon skill\n-- Skill Level: 250\n-- Delivers a single-hit attack. Damage varies with TP.\n-- In order to obtain Detonator, the quest Shoot First, Ask Questions Later must be completed.\n-- Despite the lack of a STR weaponskill mod, STR is still the most potent stat for increasing this weaponskill's damage to the point at which fSTR2 is capped.\n-- Aligned with the Flame Gorget & Light Gorget.\n-- Aligned with the Flame Belt & Light Belt.\n-- Element: None\n-- Modifiers: AGI:30%\n-- 100%TP    200%TP    300%TP\n-- 1.50      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 1.5, 2.0, 2.5 }\n    params.atkVaries           = { 2.0, 2.0, 2.0 } -- https://w.atwiki.jp/studiogobli/pages/93.html\n    params.agi_wsc             = 0.3\n    params.rangedAccuracyBonus = 100 -- https://www.ffxiah.com/forum/topic/52018/luck-of-the-draw-a-corsairs-guide-new/127/#3726841\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod  = { 1.5, 2.5, 5.0 }\n        params.agi_wsc = 0.7\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/dimidiation.lua"]={["Path"]="scripts/actions/weaponskills/dimidiation.lua",["SHA256"]="a8130b7864fe0ffdaeedd00c74c22c7687595c02bc0ae80aba1f27c0fa9fcd5e",["Text"]="-----------------------------------\n-- Dimidiation\n-- Great Sword weapon skill\n-- Skill Level: N/A\n-- Delivers a twofold attack. Damage varies with TP. Epeolatry: Aftermath effect varies with TP.\n-- Will stack with Sneak Attack.\n-- Element: None\n-- Skillchain Elements: Light/Fragmentation (Fire, Thunder, Wind, Light gorget/belt aligned)\n-- Modifiers: DEX:80%\n-- 1000 TP   2000 TP   3000 TP\n-- 2.25      4.5       6.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\n-- source https://www.bg-wiki.com/ffxi/Dimidiation, http://wiki.ffo.jp/html/31450.html\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 2.25, 4.5, 6.75 }\n    params.dex_wsc = 0.8\n    params.atkVaries = { 1.25, 1.25, 1.25 }\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/double_thrust.lua"]={["Path"]="scripts/actions/weaponskills/double_thrust.lua",["SHA256"]="eeee80a42e3514ea3c7e8cc3da477f030491ac0325b76211b604a6313320dee1",["Text"]="-----------------------------------\n-- Double Thrust\n-- Polearm weapon skill\n-- Skill Level: 5\n-- Delivers a two-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Light Gorget.\n-- Aligned with the Light Belt.\n-- Element: None\n-- Modifiers: STR:30%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.dex_wsc = 0.3\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"}};
